    Bug 2000920 - Read Calendar Event - Set Reminders data. r=freaktechnik

    **How to Test**
    - set calendar.dialogs.new.enabled pref to true
    - Open a calendar event that has reminders in it
    - The reminders should be listed and sorted
    - The delete buttons don't do anything
    - The reminder text has "before the event starts" instead of "before event", this will be updated in a follow up patch

    Differential Revision: https://phabricator.services.mozilla.com/D275697

diff --git a/mail/components/calendar/content/calendar-dialog.mjs b/mail/components/calendar/content/calendar-dialog.mjs
index e71ef67b6ae..11a4ae0af09 100644
--- a/mail/components/calendar/content/calendar-dialog.mjs
+++ b/mail/components/calendar/content/calendar-dialog.mjs
@@ -247,6 +247,17 @@ export class CalendarDialog extends PositionedDialog {

     this.#setLocation(event.getProperty("LOCATION") ?? "");

+    // Sort the reminders by offset from event date.
+    const reminders = event
+      .getAlarms()
+      .sort((a, b) =>
+        cal.alarms
+          .calculateAlarmDate(event, b)
+          .compare(cal.alarms.calculateAlarmDate(event, a))
+      );
+
+    this.querySelector("calendar-dialog-reminders-row").setReminders(reminders);
+
     const plainDescriptionPromise = this.querySelector(
       "#expandingDescription"
     ).setDescription(event.descriptionText);
@@ -271,6 +282,7 @@ export class CalendarDialog extends PositionedDialog {
     this.style.removeProperty("--calendar-bar-color");
     await this.querySelector("#expandingDescription").setDescription("");
     await this.querySelector("#expandedDescription").setDescription("");
+    this.querySelector("calendar-dialog-reminders-row").setReminders([]);
   }

   /**
diff --git a/mail/components/calendar/test/browser/browser_calendarDialog.js b/mail/components/calendar/test/browser/browser_calendarDialog.js
index bb1a5fa4293..bb2ac8870e1 100644
--- a/mail/components/calendar/test/browser/browser_calendarDialog.js
+++ b/mail/components/calendar/test/browser/browser_calendarDialog.js
@@ -601,3 +601,109 @@ add_task(async function test_calendarDailogName() {

   dialog.close();
 });
+
+add_task(async function test_dialogReminders() {
+  dialog.show();
+  const remindersRow = dialog.querySelector("calendar-dialog-reminders-row");
+  const reminderLabel = remindersRow.querySelector("#reminderCount");
+  const reminderList = remindersRow.querySelector("#reminderList");
+
+  const hourReminder = createAlarmFromDuration("-PT1H");
+  const alarms = [hourReminder];
+  const oneReminder = await createEvent({
+    name: "One Alarm",
+    calendar,
+    offset: 7,
+    alarms,
+  });
+  dialog.setCalendarEvent(oneReminder);
+
+  await BrowserTestUtils.waitForMutationCondition(
+    reminderList,
+    {
+      childList: true,
+      subtree: true,
+    },
+    () =>
+      reminderList.childNodes.length == 1 &&
+      reminderList.childNodes[0].textContent == hourReminder.toString()
+  );
+  let fluentData = document.l10n.getAttributes(reminderLabel);
+
+  Assert.equal(
+    fluentData.id,
+    "calendar-dialog-reminder-count",
+    "Reminder count label should be set"
+  );
+
+  Assert.equal(
+    fluentData.args.count,
+    1,
+    "Reminder count label should have the right count"
+  );
+
+  const dayReminder = createAlarmFromDuration("-P1D");
+  const sixDayReminder = createAlarmFromDuration("-P6D");
+  alarms.push(sixDayReminder);
+  alarms.push(dayReminder);
+
+  // Setting multiple reminders should show the load more text.
+  const multipleReminders = await createEvent({
+    name: "Multiple Alarms",
+    calendar,
+    offset: 7,
+    alarms,
+  });
+
+  dialog.setCalendarEvent(multipleReminders);
+
+  await BrowserTestUtils.waitForMutationCondition(
+    reminderList,
+    {
+      childList: true,
+      subtree: true,
+    },
+    () => reminderList.childNodes.length == 3
+  );
+
+  fluentData = document.l10n.getAttributes(reminderLabel);
+  Assert.equal(
+    fluentData.args.count,
+    3,
+    "Reminder count label should have the right count"
+  );
+
+  // Reminders should be in sequential order.
+  Assert.equal(
+    reminderList.childNodes[0].textContent,
+    hourReminder.toString(),
+    "First reminder should be in correct order"
+  );
+  Assert.equal(
+    reminderList.childNodes[1].textContent,
+    dayReminder.toString(),
+    "Second reminder should be in correct order"
+  );
+  Assert.equal(
+    reminderList.childNodes[2].textContent,
+    sixDayReminder.toString(),
+    "Third reminder should be in correct order"
+  );
+
+  resetDialog();
+  await BrowserTestUtils.waitForMutationCondition(
+    reminderList,
+    {
+      childList: true,
+      subtree: true,
+    },
+    () => reminderList.childNodes.length == 0
+  );
+
+  fluentData = document.l10n.getAttributes(reminderLabel);
+  Assert.equal(
+    fluentData.args.count,
+    0,
+    "Reminder count label should have the right count"
+  );
+});
